#!/usr/bin/env bash
#
# wrap.sh — end-of-session leak detector.
#
# Pure read-only. Tells you what's loose so you can fix it before closing
# the laptop. Catches the things you'd otherwise forget by morning.
#
# What it shows:
#   1. Uncommitted changes
#   2. Local commits that haven't been pushed to any remote
#   3. What you actually shipped today (real output, not vibes)
#   4. PRs awaiting your action
#   5. Memory-update prompt — three questions to ask yourself
#
# Generated by the `dev-workflow` skill.
#
set -euo pipefail

# ── Auto-derive paths ──────────────────────────────────────────────────────
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(dirname "$SCRIPT_DIR")"

# ── Pretty output ──────────────────────────────────────────────────────────
log()   { printf '\033[0;34m→\033[0m %s\n' "$1"; }
ok()    { printf '  \033[0;32m✓\033[0m %s\n' "$1"; }
warn()  { printf '  \033[1;33m!\033[0m %s\n' "$1"; }
note()  { printf '  %s\n' "$1"; }

cd "$REPO_ROOT"

log "Wrap-up: $(date '+%A %Y-%m-%d %H:%M')"
echo

# ── 1. Uncommitted ─────────────────────────────────────────────────────────
log "Uncommitted changes"
DIRTY=$(git status -s | wc -l | tr -d ' ')
if [[ "$DIRTY" == "0" ]]; then
  ok "working tree clean"
else
  git status -s | sed 's/^/    /'
  warn "$DIRTY files dirty — commit, stash, or accept the loss"
fi
echo

# ── 2. Unpushed local commits ──────────────────────────────────────────────
log "Local commits not on any remote"
UNPUSHED=$(git log --branches --not --remotes --oneline --decorate 2>/dev/null)
if [[ -z "$UNPUSHED" ]]; then
  ok "all local commits are pushed"
else
  echo "$UNPUSHED" | head -20 | sed 's/^/    /'
  warn "above commits exist only locally — push if they should survive a disk wipe"
fi
echo

# ── 3. Today's output ──────────────────────────────────────────────────────
log "Shipped today"
TODAY=$(date '+%Y-%m-%d')
EMAIL=$(git config user.email 2>/dev/null || echo '')
if [[ -n "$EMAIL" ]]; then
  COMMITS=$(git log --since="$TODAY 00:00" --until="$TODAY 23:59" --all --author="$EMAIL" --oneline 2>/dev/null)
  if [[ -z "$COMMITS" ]]; then
    note "(no commits today on any branch)"
  else
    echo "$COMMITS" | sed 's/^/    /'
  fi
else
  warn "git user.email not configured — can't filter today's commits"
fi
echo

# ── 4. Open PRs needing action ─────────────────────────────────────────────
log "Open PRs"
if command -v gh >/dev/null 2>&1; then
  if command -v jq >/dev/null 2>&1; then
    gh pr list --author=@me --state=open --json number,title,reviewDecision,statusCheckRollup 2>/dev/null \
      | jq -r '.[] | "  #\(.number) \(.title)\n    review: \(.reviewDecision // "PENDING")  ·  CI: \([.statusCheckRollup[]?.conclusion // "PENDING"] | unique | join(","))"' \
      || warn "gh CLI failed (auth issue?)"
  else
    gh pr list --author=@me --state=open 2>/dev/null | sed 's/^/  /' || warn "gh CLI failed"
  fi
else
  warn "gh CLI not installed — skip PR check"
fi
echo

# ── 5. Ops rota (O1 of docs/plans/ops-readiness.md) ───────────────────────
# Read-only glance: is the weekly backup green, and has a restore been
# rehearsed in the last 31 days? Needs gh; silent if it is missing.
if command -v gh >/dev/null 2>&1; then
  log "Ops rota — backups"
  last="$(gh run list --repo NikolasNeofytou/ludi-backups --workflow=backups.yml --limit 1 --json conclusion,createdAt \
    --jq '.[0] | (.conclusion // "running") + " " + (.createdAt | .[0:10])' 2>/dev/null || true)"
  case "$last" in
    success*) ok "last Backups run: $last" ;;
    "")       warn "Backups workflow has never run — set SUPABASE_PROD_DB_URL + BACKUP_PASSPHRASE on NikolasNeofytou/ludi-backups and trigger it once" ;;
    *)        warn "last Backups run: $last — check ludi-backups' Actions tab" ;;
  esac
  runbook="$REPO_ROOT/docs/runbooks/restore-from-backup.md"
  if [ -f "$runbook" ]; then
    rehearsed="$(grep -oE '^\*\*Last rehearsed:\*\* [0-9]{4}-[0-9]{2}-[0-9]{2}' "$runbook" | grep -oE '[0-9]{4}-[0-9]{2}-[0-9]{2}' || true)"
    if [ -z "$rehearsed" ]; then
      warn "restore never rehearsed — scripts/restore_backup_local.sh <artifact> with Sunday's dump"
    elif [ "$(( ( $(date +%s) - $(date -j -f %Y-%m-%d "$rehearsed" +%s 2>/dev/null || date -d "$rehearsed" +%s) ) / 86400 ))" -gt 31 ]; then
      warn "restore last rehearsed $rehearsed — more than 31 days; due"
    else
      ok "restore rehearsed $rehearsed"
    fi
  fi
  echo
fi

# ── 6. Memory prompt ───────────────────────────────────────────────────────
log "Memory check — three questions for next-session-you"
note "1. Any decision you made today that's NOT obvious from the diff?"
note "   (Why this approach over alternatives? What did you rule out?)"
note ""
note "2. Any blocker or open question you need to surface before tomorrow?"
note "   (User input needed? Awaiting external answer? Pinging someone?)"
note ""
note "3. Did your understanding of the project shift today?"
note "   (Found something the audit/memory got wrong? New constraint?)"
note ""
note "If yes to any → ask Claude to update memory before you close the session."
echo

ok "wrap done — laptop-close ready"
